window.ScripturaJastrowAppend([{"sid":"N00312","lemma":"נוֹדֵירָא","gloss":"Ver נָדֵרָא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , (נוֹדִי&#x27;) v. נָדֵרָא</p>","gloss_language":"pt-BR"},{"sid":"N00313","lemma":"נוֹדְרָן","gloss":"Ver נַדְרָן.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. נַדְרָן</p>","gloss_language":"pt-BR"},{"sid":"N00314","lemma":"נָוָה","gloss":"para ser agradável, V.נוי.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> para ser agradável, V.נוי.</p>","gloss_language":"pt-BR"},{"sid":"N00315","lemma":"נָוֶה","gloss":", (= נָאֶהFicando, bonitão.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> , (= נָאֶהFicando, bonitão.</p><p><strong>Notas e referências:</strong> Arakh. III, 1הנ&#x27; שבישראלAr. (ed.הנָּאֶה) o mais bonito em Israel, v.כָּאוּרNaz. I, 1אהא נMish. (Bab. ed.נאה; Y. ed.נָאוֶהEu serei bonito (como o nazireu).</p>","gloss_language":"pt-BR"},{"sid":"N00316","lemma":"נָוֶה","gloss":", נָוָה f. (b. h.; = נאוה, v. אָוָהII) local marcado, círculo, habitação.; אל תקרי נאוה אלא נְוֵה תהלהNão leia návah, mas n'veh de glória, isto é, uma morada de glória é a dos justos (que nenhuma mão humana é permitida para destruir).","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> , נָוָה f. (b. h.; = נאוה, v. אָוָהII) local marcado, círculo, habitação.</p><p><strong>Notas e referências:</strong> Y. Ber. IX, 13 c bot.בשביל נָוֵיהוּPor causa de sua (destruída) habitação (o Templo); Midr. Até... até Sal. XVIII. Mekh. B’shall., Shir., s. 3 (ref. toואנוהו, Ex. XV, 2)ואין נ&#x27; אלא וכ&#x27; (Nãoנאה) Naveh significa o Templo (ref. a Ps. LXXIX, 7, a. e.) Sot. 9 a (ref. a Ps. XXXIII,</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> אל תקרי נאוה אלא נְוֵה תהלהNão leia návah, mas n&#x27;veh de glória, isto é, uma morada de glória é a dos justos (que nenhuma mão humana é permitida para destruir).</p><p><strong>Notas e referências:</strong> Ib. 47 B (ref. para Hab. II, 5)לא יִנְוֶה אפי&#x27; בנ&#x27; שלוEle não será agradável (popular) mesmo em sua própria casa; B. Bath. 98 a; Yalk. Hab. 562.מוציאין מנ&#x27; הרעה נ&#x27; היפה וכ&#x27; um marido pode obrigar sua esposa a se mudar com ele de uma casa pior para uma melhor (e estilo de vida). Ib.הנ&#x27; היפה בודק, v. בָּדַקIb. 110b.לאיתויי … לנ&#x27; הרעIncluindo até uma mudança de uma casa melhor para uma casa pior, Arakh. 3 B.- Clima de Trnsf; saúde. Gen. R. s. 64מפני מה לא גזרו על הנ&#x27; … שנָוָהּ רעPor que não proibiram o ar de Gerariké? Porque o clima está ruim, Y. Shebi. VI, 36 C bot.מפני מה לא גזרו על הרוח … שנִיוְיָהּ וכIb.והרי עזה ניויה יפהMas há Gaza cujo clima é saudável. Y. B. Bath. II, 13 c topoנִיאוֹ רע(prob. ser lido:נִיוְיוֹ) uma árvore torna a vizinhança insalubre; v.נוֹי 2.</p>","gloss_language":"pt-BR"},{"sid":"N00317","lemma":"נָוֶה","gloss":", נָוֶוהIII pr.n.p. Naveh, leste de Gadara na Galiléia (v. Neub. Géogr. p. 245).","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> , נָוֶוהIII pr.n.p. Naveh, leste de Gadara na Galiléia (v. Neub. Géogr. p. 245).</p><p><strong>Notas e referências:</strong> Lev. R.S. 23, A.E., V.חַלָּמִישׁ-Ruth R. a II, 19ר&#x27; שילא דנווה; Lev. R. s. 34דנַוְהָא- Sim, Shebi.חוטא דנA linha passando por N. Neveh em Peraea].</p>","gloss_language":"pt-BR"},{"sid":"N00318","lemma":"נוֹהַג","gloss":"(נָהַג) costume;בנ' שבעולםDe acordo com o costume do mundo, normalmente, naturalmente.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> (נָהַג) costume;בנ&#x27; שבעולםDe acordo com o costume do mundo, normalmente, naturalmente.</p><p><strong>Notas e referências:</strong> Y. Ber.אֲנַנְקֵי. Gen. R. s. 70, fim; a. fr.</p>","gloss_language":"pt-BR"},{"sid":"N00319","lemma":"נוֹהֲרָא","gloss":"Ver נְהוֹר.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. נְהוֹר</p>","gloss_language":"pt-BR"},{"sid":"N00320","lemma":"נָוֶוה","gloss":"Ver נָוֶה, נָוָה..","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , נָוָוה, v. נָוֶה, נָוָה.</p>","gloss_language":"pt-BR"},{"sid":"N00321","lemma":"נַוְוטָא","gloss":"(nauta,ναύτης) marinheiro, marinheiro.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> (nauta,ναύτης) marinheiro, marinheiro.</p><p><strong>Notas e referências:</strong> - Pl.נַוְוטִים, נַוְוטִיןGen. R. s. 12ואח&quot;כ הוא מעמיד עליה נE finalmente (quando o navio terminar) ele coloca marinheiros sobre ela;ונוטיהם ונַוְוטֵיהֶם כתיבNão, ehem (Is. XLII, 5) permite a leitura v&#x27;nav ehem (e seus (os céus) marinheiros); Yalk. Is. 314חמוטי&#x27; (corr. acc.)-Cald. Pl.נַוְוטַיָּאKoh. R. para III, 6.</p>","gloss_language":"pt-BR"},{"sid":"N00322","lemma":"נַוְוטִי","gloss":"(v. נַבְטָיָיא) Nabatean.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> (v. נַבְטָיָיא) Nabatean.</p><p><strong>Notas e referências:</strong> Gen. R. s. 48; Yalk. ib. 82.נִיוְתִּי.</p>","gloss_language":"pt-BR"},{"sid":"N00323","lemma":"נֶוֶול","gloss":"Desprezo, degeneração.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> Desprezo, degeneração.</p><p><strong>Notas e referências:</strong> Tanë. Vayesheb 1להודיע נִוְולָם (נִוְולָן) para tornar conhecida sua maldade. Pl.נְוָולִיםIb.להודיע לבריות עקריהן ונִוְולֵיהֶםPara que as pessoas saibam suas origens e sua degeneração.</p>","gloss_language":"pt-BR"},{"sid":"N00324","lemma":"נָוֵול","gloss":", נָוֵל(cmp.נָבֵל) ser desfigurado, parecer repulsivo; degenerar.; Desfigurar, desonrar.; לא עצמה בלבד נִוְּולָה וכEla tem desonrado não só a si mesma, mas todas as virgens de Israel, parte.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> , נָוֵל(cmp.נָבֵל) ser desfigurado, parecer repulsivo; degenerar.</p><p><strong>Notas e referências:</strong> Tosef. Sot. XIV, 7אזלה ונָוְלָהVar.ונָבְלָה) torna-se cada vez mais corrupto.</p><p><strong>Definição:</strong> Desfigurar, desonrar.</p><p><strong>Notas e referências:</strong> B. Bath. 154 aאי … לנַוְּולוֹVocê não tem permissão para desonrá-lo. Sot. I, 6מעבירים ממנה כדי לנַוְּולָהּNós a entregamos para desonrá-la. Ned. 66 aבנות ישראל … שהעניות מְנַוַּולְתָּןAs filhas de Israel são bonitas, é só a pobreza que as faz parecer como uma casa. Sifré Deu. 240 (ref. toנבלה, Deu. XXII, 2</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> לא עצמה בלבד נִוְּולָה וכEla tem desonrado não só a si mesma, mas todas as virgens de Israel, parte.</p><p><strong>Notas e referências:</strong> Passo.מְנוּוָּל; f. מְנוּוֶּלֶת; pl.מְנוּוָּלִין, מְנוּוָּלוֹתY. Pes. VI, 33 a, sq.זבח מ&#x27; (Nãoמזבח) um sacrifício repulsivo (Pútrido) (Sabb. 116 bמוטלין כנבלה).אֶפֶשׁTosef. Sot. II, 3הרי היא בדוקה ומנEla já foi revistada e desonrada, ou seja, admitiu sua culpa. Y. M. Kat. III, implore. 81 c.שלא … מנPara que não entrem no sábado com cabelos negligenciados.אם פגע בך מנ&#x27; זה וכSe aquele feio (o tentador) te encontrar, arrastá-lo para a casa do aprendizado, ou seja, superar as inclinações malignas pelo estudo.</p>","gloss_language":"pt-BR"},{"sid":"N00325","lemma":"נְוַול","gloss":"como precedido. Pi. Ib.; ser desfigurado, desonrado.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , נְוַלEu também. Sot. 47 bומלכותא אזלא ונָוְלָא, V. Precedido.</p><p><strong>Definição:</strong> como precedido. Pi. Ib.</p><p><strong>Notas e referências:</strong> 8 b השתא נַוּוּלֵי מְנַוֵּויל לה וכJá que a lei exige sua desgraça, pode haver alguma dúvida sobre essas jóias? 11 BנִינַוְּולֵיהPodemos desonrar seu corpo (por um exame pós-morte);</p><p><strong>Definição:</strong> ser desfigurado, desonrado.</p><p><strong>Notas e referências:</strong> na mesma fonteהא קא מִינַּוֵּולEle seria desonrado (por autópsia, v. supra). B. Bath. 8 bהאי קא מינוול וכO único (colocado à morte pela espada) está desfigurado. Ib. 154bלִינַּוּוֵל ולינוולQue ele seja desonrado (por autópsia, v. supra);מְנַוַּולְתָּא.</p>","gloss_language":"pt-BR"},{"sid":"N00326","lemma":"נְוַול","gloss":", נְוַלII (denom. do próximo w.) para tecer.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> , נְוַלII (denom. do próximo w.) para tecer.</p><p><strong>Notas e referências:</strong> Snh. 95 aדהות נָוְולָא(Ms. M.קא טויא;Ed mais cedo.קא נוזלא;Srta. F.קא עזלאEstava tecendo. Gitt. 34 aיתבא ונָוְולָהEla estava sentada e tecendo.</p>","gloss_language":"pt-BR"},{"sid":"N00327","lemma":"נְוַול","gloss":", נְוַלIII,נַוְולָא I m. (v. ֵבֶלch.; Tear, também a teia no tear.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> , נְוַלIII,נַוְולָא I m. (v. ֵבֶלch.</p><p><strong>Número da acepção:</strong> 2)</p><p><strong>Definição:</strong> Tear, também a teia no tear.</p><p><strong>Notas e referências:</strong> Targ. É. XXXVIII, 12מנוול גרדאיןVar. Ed. Lag.כְּמִנְּוַול; ed.נחל, corr. acc.; oth.ed.כִּנְוַלA partir do tear dos tecelões.מיתן חד נוול וכPara colocar um tear no espaço entre duas paredes vizinhas. Bab. ib. 13b.ידעא פילכא ונ&#x27; (V. Rabb. D. S. a. l. nota 8) entende o eixo e o tear (rodo e tecelagem). Pl.נַוְולַיָּהY.L.C. (ed. Krot.דנו ליה, corr. acc.), v.מַסְמְרָא.</p>","gloss_language":"pt-BR"},{"sid":"N00328","lemma":"נַוְולָא","gloss":"Navla.","type":"Nome próprio feminino","detailsHtml":"<p><strong>Definição:</strong> Navla.</p><p><strong>Notas e referências:</strong> B. Mets. 67 aאת ונ&#x27; אחי(RashiונַוְולָהTu e N. são parentes (e ela certamente te devolverá o campo sempre que puderes redimi-lo). Ib.כל את ונ&#x27; אחי סמכא דעתיה וכSra. M. (v. Rabb. D. S. a. l. nota 80) em todos os casos em que uma expressão como &#x27;você e N. são parentes&#x27; é usado, o vendedor depende dele &amp; c. [Oth. Opin.נ&#x27;, uma expressão coloquial para &#x27;uma certa pessoa&#x27;, como nosso &#x27;N.N.&#x27;, tanto masculino quanto feminino; v. Koh. Ar. Compl. I, p. XXI].</p>","gloss_language":"pt-BR"},{"sid":"N00329","lemma":"נַוְולָה","gloss":"Ver טוֹלָא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> F.H. (um caldaísmo) =נַוְולָאI. Meïl. 18 aשכן עומד לנ&#x27; para ele (um pequeno pedaço de pano) pode ser usado para amarrar em torno da moldura do tecelão (Rashi: amarrar em torno do dedo do tecelão quando ele coloca a moldura; Var.לטולא, v. טוֹלָא).</p>","gloss_language":"pt-BR"},{"sid":"N00330","lemma":"נוון","gloss":"Ver נוֹא I.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , Pesik.נוֹא I</p>","gloss_language":"pt-BR"},{"sid":"N00331","lemma":"נוונא","gloss":"Ver צִימְרָא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , Gitt. 69 B bot.צימרא נAlguns ed., leia:גוונא, v. צִימְרָא</p>","gloss_language":"pt-BR"},{"sid":"N00332","lemma":"נַוְונֵא","gloss":"Ver נוני.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , נִוְונֶה, v. נוני</p>","gloss_language":"pt-BR"},{"sid":"N00333","lemma":"*","gloss":"נַוְוסִיןM.P. (ναῦς) navios, construção naval.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> נַוְוסִיןM.P. (ναῦς) navios, construção naval.</p><p><strong>Notas e referências:</strong> Gen. R. s. 16 Ar., ed.בנימוסין, v. נִימוֹסII.</p>","gloss_language":"pt-BR"},{"sid":"N00334","lemma":"נוורתוק","gloss":"Ver נַרְתֵּיק.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. נַרְתֵּיק</p>","gloss_language":"pt-BR"},{"sid":"N00335","lemma":"נִוְותִּי","gloss":"Ver נִיוְתִּי.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. נִיוְתִּי</p>","gloss_language":"pt-BR"},{"sid":"N00336","lemma":"נוּז","gloss":"(cmp.לוּז) para torcer, cordel; para tecer.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (cmp.לוּז) para torcer, cordel; para tecer.</p><p><strong>Notas e referências:</strong> Parte. Passo.נוּזKil. IX, 8 (Expl.ש̇ע̇ט̇נ̇ז̇) דבר שהוא ש̇וע̇ ט̇ווי ונ̇וזUma substância (de lã e linho) que é cortado e cheio, ou fiado, ou torcido (R.S. tecido); Sifré Deut. 232; Yeb. 5 b; a. e. - Nidd. 61 bעד שיהא שוע טווי ונ&#x27;até que esteja cheio, retorcido e torcido (ou tecido). Y. Kil. IX, fim, 32 dהוון אמרינן הא לָנוֹז מותרPoderíamos ter pensado, mas é permitido girar (laranja e linho).</p>","gloss_language":"pt-BR"},{"sid":"N00337","lemma":"נוּז","gloss":"A mesma parte. Passo.נִיזTarg. Y. Deu. XXII, 11 (ed. Vien.גיז, corr, acc.).","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> A mesma parte. Passo.נִיזTarg. Y. Deu. XXII, 11 (ed. Vien.גיז, corr, acc.).</p>","gloss_language":"pt-BR"},{"sid":"N00338","lemma":"נוזלא","gloss":"Ver נְוַול II.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , Snh. 95 um ed., v.נְוַולII</p>","gloss_language":"pt-BR"},{"sid":"N00339","lemma":"נוֹזְלַיָּא","gloss":"Ver נְזַל, נָזַל..","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , נוֹזְלִים, v. נְזַל, נָזַל.</p>","gloss_language":"pt-BR"},{"sid":"N00340","lemma":"נוּחַ","gloss":"(b. h.) descansar, mentir; estar à vontade, descansar satisfeito.; (fr.יָנַח); Para descansar, para descansar.; Deixar, deixar em paz, permitir.; para aliviar, resignar.; Desejar descanso (a um falecido); abençoar a memória.; para dar prazer.; para ser derrubado, descansado.; para ser libertado, para ser descansado.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (b. h.) descansar, mentir; estar à vontade, descansar satisfeito.</p><p><strong>Notas e referências:</strong> - Sabb. 7b.זרק … והלכה ונָחָה וכ&#x27; se alguém jogasse um objeto acima de dez broadths, e em seu curso ele viesse descansar em um pequeno buraco. Ib.וזרק ונָח על גביוE ele jogou um objeto e ele veio para descansar sobre ele. Gen. R. s. 25.כיון שעמד נֹחַ נָחוּQuando Noé se levantou, eles descansaram (submetido ao governo do homem, Yalk. Chr. 1072נִינּוֹחוּYalk. Gen. 42.נִחֲמָןEle os apaziguava.וכיון שעמד נֹחַ נחוE quando Noé se levantou, eles permaneceram intactos em seus túmulos, Yalk. Chr. l. c.נינוחו- Meg. 25 B, a. fr.יָנוּחוּ לו ברכות וכAs bênçãos repousam sobre sua cabeça. Sabb. 152 B, A.E.תָּנוּחַ … שהנחת וכQue a tua mente descanse, pois tu me descansaste.נָח, נוֹחַ, f. נוֹחָה; pl.נוֹחִים, נוֹחִין; נוֹחוֹתa) Descansando. Gen. R. s. 11אתם נוחיןDescanse. Y. Erub. III, fim, 21 c, a. fr.נוֹחֵי נפשcujas almas estão em repouso; a. f. b.) satisfeito. Ab. III, 10כל שרוח הבריות נ&#x27; הימנו וכEm quem a mente do homem encontra prazer, a mente de Deus encontra prazer. X, 9, a. fr.-V.נוֹחַ.</p><p><strong>Definição:</strong> (fr.יָנַח)</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Para descansar, para descansar.</p><p><strong>Notas e referências:</strong> Gen. R. l. c. (ref. para Gen. V, 29)או נח זה יְנִיחֵנוּ וכOu ele será chamado de Noa&#x27;, então deve ser lido, &#x27;ele nos colocará em repouso&#x27;, ou Na&#x27;man &amp;c. Sabb. l. c.שהֵנַחְתָּ, v. supra; (Snh. 30 bשהתנחת, v. תָּנַח; V. Rabb. D. S. a. l. nota 20). No máximo, 91 b.עלי יַנִּיחַ צדיק וכDeixe este homem justo descansar sua cabeça sobre mim B. Kam III, 1 B. Mets VI, 6הַנַּח לפניColoque-o na minha frente. Sabb. 21b.להַנִּיחָהּ על פתח וכPara colocá-lo sobre a entrada.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Deixar, deixar em paz, permitir.</p><p><strong>Notas e referências:</strong> B. Banho. IX, 1מי שמת וה&#x27; בנים וכSe uma pessoa morreu e deixou filhos e filhas. Ib. 3ראו מה שה&#x27; לנו וכ&#x27; ver o que nosso pai nos deixou. Snh. 30 aמעות שה&#x27; לו אביוdinheiro que seu pai tinha deixado para ele (sem dizer onde foi depositado). Pesik. Ps. 884אבינו ירמיה הרי אתה מַנִּיחֵנוּ שםJ., nosso pai, você nos deixará lá (em Babilônia, sem profeta)?הַנַּח להם לישראלDeixe Israel em paz. Yoma I, 4לא היו מְנִיחִים אותו וכNão o deixaram comer muito. Ab. Zar. 10 b.יַנִּיחֶנָּה, v. נוֹמִיIb. 17 aלא ה&#x27; זונה וכEle não abandonou uma única prostituta.לא ה&#x27; שלא היה מצערוEle não permitiu passar sem atormentá-lo.</p><p><strong>Número da acepção:</strong> —3)</p><p><strong>Definição:</strong> para aliviar, resignar.</p><p><strong>Notas e referências:</strong> Ab. Zar. 13 aיום שע&quot;א מֵנַחַת בו וכ&#x27; um dia em que o ídolo concede uma remissão de deveres. Ib.כל מי … ויָנִיחַ … יָנִיחַ וכPara aquele que vai pegar uma coroa de flores e colocá-la em sua cabeça (em honra da divindade), ele vai permitir uma remissão &amp;c; a. fr.</p><p><strong>Número da acepção:</strong> —4)</p><p><strong>Definição:</strong> Desejar descanso (a um falecido); abençoar a memória.</p><p><strong>Notas e referências:</strong> Yalk. Ex. 411מזכירין ומניחיןHá aqueles que são mencionados e abençoados.משחקין); Ex. R. s. 48מדכרין ומניחין; (Tan. Vayakh 4.מזכירין ומשבחים[Midr. Sam.מדכרין ומניחיןNós mencionamos e muito menos, nem elogiando nem culpando mencionando a ancestralidade].</p><p><strong>Número da acepção:</strong> —5)</p><p><strong>Definição:</strong> para dar prazer.</p><p><strong>Notas e referências:</strong> Gen. R. s. 16לַהֲנִיחוֹ וכPara lhe dar prazer, para protegê-lo.</p><p><strong>Definição:</strong> para ser derrubado, descansado.</p><p><strong>Notas e referências:</strong> Sabb. 4 a, a. fr.קלוטה כמי שהוּנְחָה דמיאUm objeto interceptado no ar.רָשׁוּת) é considerado como tendo descansado lá, v.הַנָּחָה. B. Mets. III, 4, A. E.יהא מוּנָח וכ&#x27;, v. אֵלִיָּהוּYoma 72bעדיין מונח הוא וכAinda mente, quem quiser obtê-lo. 66 aהרי כרוכה ומוּנַחַת וכEle (a lei) está embrulhado e está no canto, quem quiser estudar &amp; c; a. fr.</p><p><strong>Definição:</strong> para ser libertado, para ser descansado.</p><p><strong>Notas e referências:</strong> Cant. R. para VII, 5והגליות באות ונִינּוֹחוֹת וכE os exilados virão e descansarão debaixo dela. É. 334ונוֹחוֹתYalk. Zech. 575וחָנוֹתY. Ber. V, fim, 9 dבטוח אני שנ&#x27; בנו וכEstou confiante que o filho de... se recuperará de sua doença. Gen. R. s. 13נִינּוֹחוּEles estão aliviados (fora de perigo). Yalk. Chr. 1072, v. supra; A.E.</p>","gloss_language":"pt-BR"},{"sid":"N00341","lemma":"נוּחַ","gloss":", אַנַּח; para dar descanso, para aliviar.; para descansar, abaixar, deixar em paz.; para ser aliviado, se recuperar.; Para ser colocado, colocado.; (v. נִיחָא) para ser satisfatório.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> mesmo significado</p><p><strong>Informações do original:</strong> ch.</p><p><strong>Notas e referências:</strong> Targ. Gen II, 2ונַחTarg. II Sam. XXI, 10לִמְנָח- Parte.נְיָיח, נְיָחTarg. Y. Num. XXIII, 24. Trabalho III, 25נְיָיחִית(Ms.נָחִית- B. Mets.נַח זעפאA tempestade diminuiu. Ib.כי הוה נָיְחָא נפשיהquando sua alma estava em repouso (quando ele estava morto). Ib.תִּינַח נפשיה וכDeixe-me morrer, do que ser entregue. Ib.ההוא יומא דנח נפשיהNo dia em que ele morreu. Keth. 104 a, a. fr.נח נפשיה ד־- Está morto. Yoma 20bנִינַח מרDeixe-o em paz, senhor. Sabb. 3 por bot.גופו מֵינַח נָיֵיחSra. M. (v. Rabb. D. S. A. l. nota) seu corpo estava descansando (e ele o levantou do chão em movimento). Ib. 5b.מים מי עבידי דנָיְיחֵיÉ possível que a água esteja em repouso a qualquer momento?</p><p><strong>Definição:</strong> , אַנַּח</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> para dar descanso, para aliviar.</p><p><strong>Notas e referências:</strong> Targ. O. Deu. III, 20דִּינִיחַ(ed. Vien.דִּי יְנִיחַ); Y. דְּיָנִיחַTarg. Ezek. XXIV, 13; a. fr. - Targ. II Chr. XV, 15; XX, 30אַנְיָיחLag.אניח; fr.נְיָיח, v. supra).לַאֲנוּחֵי דעתיה וכPara acalmar a mente de...מדכרין ומניחין, V. Preced.]</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> para descansar, abaixar, deixar em paz.</p><p><strong>Notas e referências:</strong> Targ. Ex. XXXII, 10אַנַּח(O. ed. Vien.הַנַּחַ; ed. Berl.אָTarg. Jud. VI, 18 anos.כי מַנַּח ליהQuando ele abaixa. Keth. 47 b.אֲנוּחֵי נַנְחִינְהוּEle deve deixá-los mentir.מַנַּח; f. מַנְּחָא; pl.מַנְּחֵי46 um robô.דמ&#x27; ביה וכ&#x27;, v. וַרְדָּאKeth, 84 b.דמנחי היכאOnde foram colocados (na hora da morte)?</p><p><strong>Definição:</strong> para ser aliviado, se recuperar.</p><p><strong>Notas e referências:</strong> Targ. Y. Lev. XXVI, 35.</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Para ser colocado, colocado.</p><p><strong>Notas e referências:</strong> B. Bath. 14 bדמִתְנַח ליה וכ&#x27; (Rashiדמַנַּח, v. supra) foi colocado ao lado, a. E.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> (v. נִיחָא) para ser satisfatório.</p><p><strong>Notas e referências:</strong> Kidd. 45 B.אִיתְנוּחֵי אִיתְנָחָא ליהFoi agradável para ele. B. Bath. 129 aאִיתְנָחַת לן חדאSra. R. (v. Rabb. D. S. a. l. nota 60; ed.אנחתת, v. נְחַתUm de seus argumentos foi satisfatoriamente eliminado para nós. Contr.אִינַּח.—תִּינַּח, הָתִינַּח(um termo dialético) isso pode ser certo, aceitável, pode fazer bem. Sabb. 5 aהת&#x27; ברשות היחיד וכIsso pode ser aceitável em relação a um terreno privado coberto, mas...ת&#x27; גדול וכIsso pode se aplicar a um adulto, mas...</p>","gloss_language":"pt-BR"},{"sid":"N00342","lemma":"נוֹחַ","gloss":"Descansar, satisfação.","type":"Substantivo masculino","detailsHtml":"<p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> Descansar, satisfação.</p><p><strong>Notas e referências:</strong> Tosef. Sot. XIV, 10ואין נ&#x27; בעולם לישראלE não há descanso no mundo para Israel, Sot. 47 bאין נ&#x27; בעולםNão há satisfação no mundo.</p>","gloss_language":"pt-BR"},{"sid":"N00343","lemma":"נוֹחַ","gloss":"(precedida. wds.); Agradável, gentil.; Calma.; נ' לוÉ bom para.","type":"Substantivo feminino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: ,, נוֹחָה</p><p><strong>Definição:</strong> (precedida. wds.)</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Agradável, gentil.</p><p><strong>Notas e referências:</strong> Ab. III, 12הוי קל לראש ונ&#x27; לתשחורתSeja rápido (para servir) ao seu superior, e gentil com a juventude; Y. Taan. II, 65 b bot.ונ&#x27; תשח&#x27; (corr. acc.).</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Calma.</p><p><strong>Notas e referências:</strong> Gen. R. s. 17מפני מה האיש נ&#x27; להתפתות וכPor que o homem é facilmente pacificado, e a mulher não? Ab. V, 11נ&#x27; לכעוס ונ&#x27; וכfacilmente irritado e facilmente reconciliado, Opp.קשהYalk. Deu. 845.נֹחַ לקנות שונא וכ&#x27; é fácil adquirir um inimigo, mas difícil adquirir um amigo;נח לעלות לבימה וכ&#x27; é fácil ser levado para a plataforma da corte, mas difícil de descer (ser absolvido); a. fr. - Pl.נוֹחִים, נוֹחוֹת, נֹח&#x27;. Gen. R. s. 90ונח&#x27;; Yalk. ib. 148ונוח&#x27;, v. יָפַע.</p><p><strong>Número da acepção:</strong> —3)</p><p><strong>Definição:</strong> נ&#x27; לוÉ bom para.</p><p><strong>Notas e referências:</strong> Erub. 13 bנ&#x27; לו לאדם שלא נברא יותר וכTeria sido melhor para o homem não ter nascido em tudo do que &amp; c. Sabb. 56 bנ&#x27; לו לאותו … ואל וכTeria sido melhor para aquele homem piedoso, se ele fosse um escravo em um templo idólatra, só que não poderia ser escrito sobre ele.</p>","gloss_language":"pt-BR"},{"sid":"N00344","lemma":"נוֹחַ","gloss":"Ver נֹחַ.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> P.N.M., V.נֹחַ</p>","gloss_language":"pt-BR"},{"sid":"N00345","lemma":"נוֹחֵשׁ","gloss":", pl.נוֹחֲשִׁים, v. נָחַשׁ.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> , pl.נוֹחֲשִׁים, v. נָחַשׁ.</p>","gloss_language":"pt-BR"},{"sid":"N00346","lemma":"נוּט","gloss":"(b. h.; cmp.מוּט a. נוּד) para agitar.; Assustar.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> ch.</p><p><strong>Definição:</strong> (b. h.; cmp.מוּט a. נוּד) para agitar.</p><p><strong>Definição:</strong> Assustar.</p><p><strong>Notas e referências:</strong> Targ. Y. Lev. XXVI, 6, V.נוּדch.</p>","gloss_language":"pt-BR"},{"sid":"N00347","lemma":"נוטומי","gloss":"Y. Maas Sh. II, 53 cא\"ר יונה והן נוטי נ', uma corrupção, problema. Uma tautografia corrupta deא\"ר יונה והוא שליקט מיכן ומוכןna mesma fonte","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> Y. Maas Sh. II, 53 cא&quot;ר יונה והן נוטי נ&#x27;, uma corrupção, problema. Uma tautografia corrupta deא&quot;ר יונה והוא שליקט מיכן ומוכןna mesma fonte</p>","gloss_language":"pt-BR"},{"sid":"N00348","lemma":"נוטי","gloss":"Ver preced..","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , V. Precedido.</p>","gloss_language":"pt-BR"},{"sid":"N00349","lemma":"נוטירין","gloss":"Ver next w..","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , V. Próximo W.</p>","gloss_language":"pt-BR"},{"sid":"N00350","lemma":"נוֹטָרִין","gloss":"Acusações.; (notarius, -ii) funcionários.","type":"Substantivo masculino plural","detailsHtml":"<p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Acusações.</p><p><strong>Notas e referências:</strong> Ex. R. s. 31כיון שקרא נ&#x27; שלו וכE quando ele leu as acusações contra ele, ele disse, e ele ainda vive?</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> (notarius, -ii) funcionários.</p><p><strong>Notas e referências:</strong> Sot. 35 Bשיגרו נ&#x27; שלהם וכ&#x27; (NãoנוטיריןEles enviaram seus funcionários que tiraram o limão e copiaram a inscrição; Y. ib. VIII, 21 dמשלחין נוֹטָרֵיהֶן, Tosef. ib. VIII, 6ושלחו נוטיריןEd. Zuck. Var.נטורין[Sifré Num. 157נוטרים, v. נָטַר].</p>","gloss_language":"pt-BR"},{"sid":"N00351","lemma":"נוֹטָרִיקוֹן","gloss":"(νοταρικόν, sub.μεθόδιον, S.) método estenógrafo, abreviação.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> (νοταρικόν, sub.μεθόδιον, S.) método estenógrafo, abreviação.</p><p><strong>Notas e referências:</strong> Sabb. XII, 5כתב אות אחת נSe alguém escreveu (no Sabbath) uma letra como abreviação (e.g.ק&#x27;paraקרבן). Ib. 105 aלשון נO método acróstico da falaא̇ב̇ ה̇מ̇ו̇ןGen. XVII, 5.אֹב, בֹחור, חֹביב, מֹלך, וֹתיק, נֹאמן). Ib.אנכי נ&#x27;, v. אָנֹכִי; a. fr.—Trnsf.לשון נPor uma simples dica. Deu, R.S. 2, v.קִידּוּשׁ</p>","gloss_language":"pt-BR"},{"sid":"N00352","lemma":"נוי","gloss":"(b. h.) estar se tornando, agradável.; Para embelezar, adornar.; וכי … לַנְווֹת את בוראוÉ possível para o homem embelezar seu Criador? B’shall, Shir.; Adornar a si mesmo.; Tornar-se bonito, ser vaidoso.; para embelezar.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: נָוָה</p><p><strong>Definição:</strong> (b. h.) estar se tornando, agradável.</p><p><strong>Notas e referências:</strong> Sot. 47 B, A.E.יִנְוֶה, v. נָוֶהII.</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Para embelezar, adornar.</p><p><strong>Notas e referências:</strong> Y. Peah I, 15 B (ref. ao Ex. XV,</p><p><strong>Número da acepção:</strong> 2)</p><p><strong>Definição:</strong> וכי … לַנְווֹת את בוראוÉ possível para o homem embelezar seu Criador? B’shall, Shir.</p><p><strong>Notas e referências:</strong> , s. 3 להַנְווֹת קונו* (Yalk. Ex. 244להשוות לקונו, v. infra). -2) para igual, adaptar-se a si mesmo. Sabb. 133 B (Expl.ואנוהו, Ex. l. c.)הוי דומה לוSeja como Ele, Mekh.נדמה לוVamos ser como Ele. Yalk. L.C.וכי … להשוות לקוניÉ possível para o homem igualar seu Criador?</p><p><strong>Definição:</strong> Adornar a si mesmo.</p><p><strong>Notas e referências:</strong> Mekh. l. c.אֶנָּוֶוה לפניו, v. נָאָה.</p><p><strong>Definição:</strong> Tornar-se bonito, ser vaidoso.</p><p><strong>Notas e referências:</strong> Sot. Eu, 8אבשלום נ&#x27; בשערוY.ed. (Mish. a. Bab. ed. 9 b)נתגאהAbsalão era vaidoso de seu cabelo.</p><p><strong>Definição:</strong> para embelezar.</p><p><strong>Notas e referências:</strong> Mekh. l. c. (ref. toואניהו, v. supra)נַיֶּינּוּ ושַׁבְּחוּ להב&quot;ה וכEmbelezai-O e louvai ao Senhor perante todas as nações. L.C.אגיד נאותיו ושְׁבָחוֹ וכ&#x27;, v. נָאֶה).</p>","gloss_language":"pt-BR"},{"sid":"N00353","lemma":"נוי","gloss":"Hithpa.הִתְנַוֶּהPara cair, V.נִוְנֶה.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: נָוָה</p><p><strong>Definição:</strong> Hithpa.הִתְנַוֶּהPara cair, V.נִוְנֶה.</p>","gloss_language":"pt-BR"},{"sid":"N00354","lemma":"נוֹי","gloss":"(נָוָה, נָאָה); Beleza, ornamento.; נוֹיouנְוָיי (= נָוֶוהII) habitação, clima.","type":"Substantivo masculino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: נוֹא</p><p><strong>Definição:</strong> (נָוָה, נָאָה)</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Beleza, ornamento.</p><p><strong>Notas e referências:</strong> Kel. XIV, 2עשאן לנויDehr.לנוֹאיEle os apegava à ornamentação. Yeb. 39b.הכונס את יבמתו … לשם נ&quot;Aquele que se casou com a esposa de seu irmão falecido (v.יְבָמָה) por sua beleza (não com a intenção de perpetuar o nome de seu irmão). Y. Maasr. III, fim, 51 aלנוֹיָיהּ של חצרPara embelezar o tribunal. Zeb. 54 B (jogar emבנוית, I Sam. XIX, 18)עוסקין בנוֹיוֹ של וכ&quot;engajado no enfeite do mundo (consultando sobre a construção do Templo). Koh. R. para II, 12והוא נוֹאוֹe esta (o nariz) é a beleza do homem; Gen. R. s. 12נאה(corr. acc.). Pesik.בעלת נ&#x27; uma mulher bonita, a. fr. - Pl.נוֹיוֹתYalk. Cant. 988בנוֹיוֹתָיו(nãoבנויתיו), v. נָאֶה.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> נוֹיouנְוָיי (= נָוֶוהII) habitação, clima.</p><p><strong>Notas e referências:</strong> B. Bath. 24 bמשום נויי העירPor causa da saúde da cidade (que sofre de árvores; Rashi: por causa da beleza da cidade que requer um espaço aberto ao redor); Y. ib. II, 13 c topoשניאו רע; Y. Shebi. VI, 36 c bot.נִיוְיָהּ, v. נָוֶהII.</p>","gloss_language":"pt-BR"},{"sid":"N00355","lemma":"נְוַי","gloss":"Ver נְוַאי.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , pr.n. pl., v.נְוַאי</p>","gloss_language":"pt-BR"},{"sid":"N00356","lemma":"נְוָיָה","gloss":"Ver נְבָיָיה.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. נְבָיָיה</p>","gloss_language":"pt-BR"},{"sid":"N00357","lemma":"נוּךְ","gloss":"(נָכָהDiminução, parte menor.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> (נָכָהDiminução, parte menor.</p><p><strong>Notas e referências:</strong> Sifra M’tsorza, Neg., Par. 3, cap. III (Expl.תְּנוּךְ, Lev. XIV, 14)תוך נ&#x27; וכDentro da hélice menor, que é a anti-hélice, v.גְּדֵירָא.</p>","gloss_language":"pt-BR"},{"sid":"N00358","lemma":"נוּכְזְרָיָא","gloss":"Ver נַכְזְרָיָא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. נַכְזְרָיָא</p>","gloss_language":"pt-BR"},{"sid":"N00359","lemma":"נוּכְרָא","gloss":"Estranho, estranho, gentil.","type":"Substantivo masculino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: נוּכְרָאָה, נוּכְרַי, נוּכְרָיָא</p><p><strong>Informações do original:</strong> נָכְרִי</p><p><strong>Informações do original:</strong> ch. = h.</p><p><strong>Definição:</strong> Estranho, estranho, gentil.</p><p><strong>Notas e referências:</strong> Targ. O. Deut. XVII, 15 anos.נוכריאAlguns ed., v.נַכְזְרָיָא- Sabb. 65 b.גופא נוכראהO corpo de outra pessoa, V.גּוּפָא- Pl.נוּכְרָאִיןTarg, Lam, V, 2 anos, e...נוּכְרָאָה, נוּכְרָיָיא, נוּכְרֵיתָאTarg. Ex. II, 22. Trabalho XIX, 17 anos.נוּכְרֵיתָאUma mulher gentil. Targ. Prov. V, 20 anos. XXVII, 4נוכריתאSra. Abominação.מְרַחַקְתָּא), ed.נִכְזְרָיוּתָא- Pl.נוּכְרָאָן, נוּכְרֵיָיתָאTarg. Gen. XXXI, 15 (nãoנוּכְרֵיתָא).</p>","gloss_language":"pt-BR"},{"sid":"N00360","lemma":"נוּכְרֵיתָא","gloss":"Ver preced..","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , V. Precedido.</p>","gloss_language":"pt-BR"},{"sid":"N00361","lemma":"נוּכְתְּתָא","gloss":"(נְכַת) = h. נֶשֶׁךְ, usura.","type":"Substantivo feminino","detailsHtml":"<p><strong>Definição:</strong> (נְכַת) = h. נֶשֶׁךְ, usura.</p><p><strong>Notas e referências:</strong> Targ. Prov. XXVIII, 8.</p>","gloss_language":"pt-BR"},{"sid":"N00362","lemma":"נָוֵל","gloss":"&c., V. subנוו'.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: נְוַל, נַוְלָא</p><p><strong>Notas e referências:</strong> &amp;c., V. subנוו&#x27;.</p>","gloss_language":"pt-BR"},{"sid":"N00363","lemma":"נוֹלָד","gloss":"Ver יָלַד.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. יָלַד</p>","gloss_language":"pt-BR"},{"sid":"N00364","lemma":"נְוָלוּ","gloss":"(נְוַולI) ofensiva; esterco, fossa.","type":"Substantivo feminino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: נְוָלִי</p><p><strong>Definição:</strong> (נְוַולI) ofensiva; esterco, fossa.</p><p><strong>Notas e referências:</strong> Ezra VI, 11.</p>","gloss_language":"pt-BR"},{"sid":"N00365","lemma":"נוּם","gloss":"(denom. deנְאוּם, comoנָאַם, Jer. XXIII, 3; Para falar, digamos.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (denom. deנְאוּם, comoנָאַם, Jer. XXIII, 3</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Para falar, digamos.</p><p><strong>Notas e referências:</strong> Cant. R. para I, 1שנָם, v. לְמוּאֵלTosef. Ohol. IV, 14נם לי הןEle me disse, sim. Ib.נַמְתִּיEu disse: &quot;Parte&quot;.נוֹמֶה(fr.נמה), fr. que (como em Chald.)נוֹמֵיתִי, נוֹמִינוּ# Yeb. XVI, 7 (122 a)ונומיתי לו(Y.ed.ונִימֵּיתִי, Pi.) e eu disse a ele. Ib.נוֹמֵיתBab. Ed.נוֹמַתMish.אמרהEla disse. Gitt. VI, 7נומינו לשליח(Ar.נִמִּינוּDissemos ao mensageiro: XII, 12 c topoונומה לי(ed. Krot.ונִימָּה); Y. Naz. II, fim, 51 cנִימָּא(fr.נמא); Tosef. ib. IV, 7נם; Sifre Num. 22נָאַם, נָאַמְתִּיTrato. Der. Er. Ch. IIהמְנַמִּין והמפפין בידיהםque fazem movimentos com as mãos quando falam. Ohol. V, 12נמיתיEd. Zuck., oth. Ed.נמתי, leia:נעניתי, v. עָנָהII.]</p>","gloss_language":"pt-BR"},{"sid":"N00366","lemma":"נוּם","gloss":"(b. h.) para dormir.; Nithpalp.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (b. h.) para dormir.</p><p><strong>Definição:</strong> Nithpalp.</p><p><strong>Notas e referências:</strong> נִתְנַמְנֵםpara estar sonolento, para dormir. Meg. II, 2ומִתְנַמְנֵםou (ele leu o Livro de Ester) enquanto ele estava meio adormecido. Pes. X, 8נִתְנַמְנְמוּSe eles cochilaram (na mesa), opp.נרדמו. Ib. 120 b; Meg. 18 bהיכי דמי נתנמנםQue condição significa Nithnamnem?, v.ניםYoma I, 7בקש להִתְנַמְנֵםSe ele mostrasse disposição para adormecer, Koh R. a V, 11 (em Chald. dict.)נתנ&#x27; עבדא ודמך ליהO escravo foi vencido pela sonolência e adormeceu.</p>","gloss_language":"pt-BR"},{"sid":"N00367","lemma":"נוּם","gloss":"para ficar sonolento; para dormir.; para ficar sonolento.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> mesmo significado</p><p><strong>Informações do original:</strong> ch.</p><p><strong>Notas e referências:</strong> Targ. Is. V, 27; e.נָאִים, נָיֵים, נָיֵםTarg. Ps. CXXI, 3, sq.ינוםSrta.נָיֵם, נאים- Erub. 65 aלא בעי מר מֵינַם פורתאVocê não tiraria um cochilo? Ib.השתא … ונֵינוּם טובאLogo chegarão os dias que são longos e ainda curtos, quando teremos um longo sono. Pes. 120 b.מינם קא נאים מרVocê estava dormindo?כי ניים ושכיב וכRab deve ter dito isso quando estava com sono e indo para a cama.גאני, v. גְּנֵיSnh. 7 aהיא נָיְימָא, v. דִּיקוּלָא.</p><p><strong>Definição:</strong> para ficar sonolento; para dormir.</p><p><strong>Notas e referências:</strong> Pes. l. c.אין נַמְנוּמֵי קא מְנַמְנְמִיNão, eu estava cochilando. Kidd. 17 B, V.הֵינוּמָא-Espero estar em coma, estar morrendo. M. Kat. 28 aדהוה קא מְנַמְנֵםque ele estava morrendo. Kidd. 72 por bot.כי הוה קא מנ&#x27; רביAr. (ed.ניחא נפשיה) quando Rabino estava morrendo.</p><p><strong>Definição:</strong> para ficar sonolento.</p><p><strong>Notas e referências:</strong> Targ. Ps. LXXVI, 6. Eu, três um robô.שריין מִתְנַמְנְמִיןEles começaram a ficar sonolentos. Y. Meg. II, 73 um robô.</p>","gloss_language":"pt-BR"},{"sid":"N00368","lemma":"נוֹמָא","gloss":"Ver נוֹמִי.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. נוֹמִי</p>","gloss_language":"pt-BR"},{"sid":"N00369","lemma":"נוֹמֶה","gloss":"Ver נוּם I.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. נוּם I</p>","gloss_language":"pt-BR"},{"sid":"N00370","lemma":"נומויון","gloss":"Ver נוּמִירוֹן.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. נוּמִירוֹן</p>","gloss_language":"pt-BR"},{"sid":"N00371","lemma":"נוֹמוֹס","gloss":"(νόμος) lei, costume.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> (νόμος) lei, costume.</p><p><strong>Notas e referências:</strong> Y.R. Hash. Eu, 57 um bot., v.אַגְרָפוֹסLev. R.S. 7, fimנ&#x27; הוא וקילוסין הואAr. ed. Koh.נימוס קלוסיםÉ uma lei e um comando. - O quê? Principalmente.נִימוֹס.</p>","gloss_language":"pt-BR"},{"sid":"N00372","lemma":"נוֹמִי","gloss":"(νομήDor corrosiva, úlcera.","type":"Substantivo feminino","detailsHtml":"<p><strong>Definição:</strong> (νομήDor corrosiva, úlcera.</p><p><strong>Notas e referências:</strong> Ab. Zar. 10 b.מי שעלתה לו נ&#x27; וכAr. ed. Koh. (ed.שעלה … נימאSe alguém tem uma úlcera no pé, deve cortá-la e viver, ou deixá-la ir e morrer?עלתה נ&#x27; בבשרם וכ&#x27; (algum Ed.נמי) eles têm uma ferida ulcerante ..., e os médicos aconselham circuncisão. Ib.ונ̇מ̇ל̇ת̇ם, Gen. XVII, 1</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Notas e referências:</strong> כנ̇ומ̇י היא ת̇ל̇ויה בגוףÉ como uma ferida alimentar pendurada no corpo. Sifré Deu. 45 anos.ואם … הרי אתה מעלה נימיMas se o removeres, causarás ulceração;</p>","gloss_language":"pt-BR"},{"sid":"N00373","lemma":"נומיון","gloss":"Ver next w..","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , V. Próximo W.</p>","gloss_language":"pt-BR"},{"sid":"N00374","lemma":"נוּמִירוֹן","gloss":"(numero,νούμερος, -ον, S.) uma divisão de tropas.","type":"Substantivo feminino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: נוּמִירָן</p><p><strong>Definição:</strong> (numero,νούμερος, -ον, S.) uma divisão de tropas.</p><p><strong>Notas e referências:</strong> Mekh. B’shall., s. 1שאין נ&#x27; אחת בטילה(nãoואיןNenhuma divisão (do império romano) está desempregada, Yalk. Ex. 230נומויון, נומיון(corr. acc.).</p>","gloss_language":"pt-BR"},{"sid":"N00375","lemma":"נוּמִיתָא","gloss":"Ver נוּמְתָּא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. נוּמְתָּא</p>","gloss_language":"pt-BR"},{"sid":"N00376","lemma":"נוֹמָס","gloss":"Ver נוֹמוֹס.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. נוֹמוֹס</p>","gloss_language":"pt-BR"},{"sid":"N00377","lemma":"נוּמְתָּא","gloss":"(נוּםII) sono.","type":"Substantivo feminino","detailsHtml":"<p><strong>Definição:</strong> (נוּםII) sono.</p><p><strong>Notas e referências:</strong> Targ. Prov. VI, 10 (algum Ed.נוּמִיתָא).</p>","gloss_language":"pt-BR"},{"sid":"N00378","lemma":"נו\"ן","gloss":"A carta Nun.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> A carta Nun.</p><p><strong>Notas e referências:</strong> Ned. 54 b, v. próximo W. Sabb. 104 a. e. - PL.נוּנִיןIb. 103b</p>","gloss_language":"pt-BR"},{"sid":"N00379","lemma":"נוּן","gloss":"(Contr. deנענע, v. cartaו; cmp.זִיז = זוזו) peixe.","type":"Substantivo masculino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: נוּנָא</p><p><strong>Definição:</strong> (Contr. deנענע, v. cartaו; cmp.זִיז = זוזו) peixe.</p><p><strong>Notas e referências:</strong> Targ. Jon. II, 1.שלי נונא, v. שָׁלֵינוּנָא-Ned. 54 bנו&quot;ן סמ&quot;ך עי&quot;ן נ&#x27; סמא לעיניםA sucessão das letras Nun, Samekh, Ayin serve como uma intimação, &#x27;peixe é um remédio para os olhos&#x27;. Gen. R. s. 11, a. fr. - Ab. Zar. 39 a.שפר נ&#x27; (καλλίχθος) sh’far nuna, nome de um peixe do gênero antias;קדש נ&#x27; (ἱερὸς ἰχθύςK’dash nuna, um nome para Antias, chamado por algunsקבר נ&#x27; (Ar.קברנונא, em um w.) &#x27;bar nuna (Grave-fish); [para corr. vers., v. Rabb. D. S. a. l. nota 70, a. Tosaf. a. l.]. Ib.לשפרנונא(Ms. M. em duas palavras). Pl.נוּנִין, נוּנַיָּא, נוּנַיָּיה, נוּנֵיTarg. Dez. IV, 18 anos, Y. Naz. IX, 57 d, v.צְלֵיNed IV, por favor.חל; a. fr.</p>","gloss_language":"pt-BR"},{"sid":"N00380","lemma":"נוני","gloss":"(= נונו = נענע, v. preced.; cmp.צִוְצֵי, s. v. צָוַץ) para ser terno, delicado.; Tornar-se delicado, falhar, cair.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: נִוְנֶה</p><p><strong>Definição:</strong> (= נונו = נענע, v. preced.; cmp.צִוְצֵי, s. v. צָוַץ) para ser terno, delicado.</p><p><strong>Definição:</strong> Tornar-se delicado, falhar, cair.</p><p><strong>Notas e referências:</strong> B. Kam. 91 aאמדוהו והיה מִתְנַוְנֶה והולך(Ms. M.מִתְנַוְונֶה; ed. Sonc.מִתְנַוֶּה) se os peritos declarassem seus ferimentos como curáveis (e o tribunal avaliasse os danos em conformidade), mas ele continua caindo. 57 Bמִתְנַוְונָה והולכת(Tosef. ib. III, 9מכחשת) se o animal perder a carne, opp.משבחתSot. III, 5; ib. 6 aמתנוונא(corr. acc.). Ib. 26 aבמתנונה דרך איבריםQuando ela está doente em todo o corpo (não sofrendo localmente como previsto para a mulher sem fé, Num. V, 27); Y. ib. III, 19 um bot.המִתְנַוָּוה.</p>","gloss_language":"pt-BR"},{"sid":"N00381","lemma":"נַוְנֵי","gloss":"Ithpalp.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> ch.,</p><p><strong>Definição:</strong> Ithpalp.</p><p><strong>Notas e referências:</strong> אִתְנַוְּנֵיMesmo. Sot. 6 aהיא מִתְנַוְונָאEla estava caindo (antes de testemunhas se levantarem contra ela).</p>","gloss_language":"pt-BR"},{"sid":"N00382","lemma":"נוּס","gloss":"(b. h.) para fugir.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (b. h.) para fugir.</p><p><strong>Notas e referências:</strong> Ex. R. s. 3למה נָסPor que ele fugiu (antes da serpente)? Yalk. Ex. 237בכל מקים שהיה מצרי נס וכ&quot;Se um egípcio fugisse, o mar correria contra ele; Mekh. B’shall. 6מצרים נָסִים; a. fr.</p>","gloss_language":"pt-BR"},{"sid":"N00383","lemma":"נוּס","gloss":"Ver נְסִס.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> ch., v.נְסִס</p>","gloss_language":"pt-BR"},{"sid":"N00384","lemma":"נוּעַ","gloss":"(b. h.) para agitar, mover; para ser macio.; Para agitar, agitar, assustar.; ; Tosef. ib. XII, 10מנ' קולו.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (b. h.) para agitar, mover; para ser macio.</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Para agitar, agitar, assustar.</p><p><strong>Notas e referências:</strong> Tosef. Apostas. Eu, 8עד שיְנַעֲנֵעַA menos que ele agitou o pássaro (no dia anterior, por que ato ele fez dele sua propriedade e designou-o para o abate); Y. ib. I, 60 c top.אלא אם כן ני&#x27; מבעוד יוםSuc. III, 1כדי לנַעֲנֵעַ בוGrande o suficiente para apertar na mão dele. Ib. 9והיכן היו מְנַעְנְעִיםE em que passagens do Hallel eles balançaram (o Lulab)? Sabb. XX, 5 (141 a)הקש … לא יְנַעְנְעוֹ וכ&#x27; (Bab. a. Y. ed.יְנַעְנְעֶנּוּNão deve agitar com sua mão a palha...נ&#x27; (ב)ראשCurvar a cabeça. Ber. 28 b.כיון שנ&#x27; ראשו וכSe ele se curvar, é suficiente. Yeb. 121 aוכל גל … נִעְנַעְתִּי לו ראשיE quando cada onda vinha, eu mergulhava minha cabeça (para deixá-la passar sobre mim). Ib.אם … יְנַעֲנֵעַ לו ראשוSe as pessoas más vierem ao homem, deixe-o abaixar a cabeça. Pesik. R.S. 37ומנענעים בראשיהםE balançaram suas cabeças (em escárnio, ref. a Ps. XXII, 8). Prov. 953ומנענע בו בקולוe canta com uma voz trêmula;מנענע בקולוSra. K. (v. Rabb. D. S. a. l. nota</p><p><strong>Número da acepção:</strong> 2)</p><p><strong>Definição:</strong> ; Tosef. ib. XII, 10מנ&#x27; קולו.</p><p><strong>Notas e referências:</strong> - Parte, passo.מְנוּעֲנָע, pl.מְנוּעֲנָעִיןAposto 25 a.המקושרים והמ&#x27; os pássaros designados um dia antes do Dia Santo por estar amarrado ou por ser agitado; ib.והמקושרין והמ&#x27; בכ&quot;מ אסוריןPássaros encontrados em qualquer lugar amarrados ou agitados são proibidos de serem tomados (porque alguém tomou posse deles); Tosef. ib. I, 10והמְנוּעָנִיןVar.והמנענין, corr. acc.2) para se mover em direções diferentes, para introduzir um instrumento cirúrgico. Nidd. 25 b, v.סִכְסֵךְ I.</p>","gloss_language":"pt-BR"},{"sid":"N00385","lemma":"נוּעַ","gloss":", totter.; Para sacudir.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> mesmo significado</p><p><strong>Informações do original:</strong> ch.</p><p><strong>Definição:</strong> , totter.</p><p><strong>Notas e referências:</strong> Targ. Ps. CVII, 27.</p><p><strong>Definição:</strong> Para sacudir.</p><p><strong>Notas e referências:</strong> Gen. R. s. 75, implore.דמְנַעְנָה (= דמנענעה), v. נְעַר.</p>","gloss_language":"pt-BR"},{"sid":"N00386","lemma":"נועדן","gloss":"Ver נַעֲרָן.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: נוערן</p><p><strong>Notas e referências:</strong> , v. נַעֲרָן</p>","gloss_language":"pt-BR"},{"sid":"N00387","lemma":"נוּף","gloss":"(b. h.) para se mover no ar, para voar.; Para balançar, acenar.; Para fã.; Para balançar, fã.; para ser winnowed.; Para balançar a si mesmo, para voar, para ser orgulhoso.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (b. h.) para se mover no ar, para voar.</p><p><strong>Notas e referências:</strong> [Yalk. Ps. 676שהוא נפה, leia:שהיא צפה, v. צוּף.]</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Para balançar, acenar.</p><p><strong>Notas e referências:</strong> Homens. 61 B.כהן מניח … ומֵנִיףO padre coloca a mão debaixo do dono da oferta e das ondas. Ib.אין העכ&quot;ום מְנִיפִיןGentis não são autorizados a acenar suas oferendas;אין הנשים מְנִיפוֹתMulheres não são permitidas.וכול יָנִיף ויחזור ויניףAcho que ele deve acenar duas vezes. Snh. VI, 1מֵנִיף בסודריןSuc. 51 b. Pesik. R. s. 41 (ref. toיפה נוף, Ps. XLVIII, 3)היפה שהיא עתידה להָנִיף את וכA bela que está destinada a balançar as nações, Yalk. Ps. 755; Yalk. Ex. 417שהיא מְנִיפָה לאו&quot;ה(ref. para Is. XXX, 28); a. fr.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Para fã.</p><p><strong>Notas e referências:</strong> B. Mets. 86 aהָנִיפִי עלי, v. מְנִיפָאY. Yoma I, 38 cומניפין לרבוניהםe fãs de seus mestres. Pesik. R.L.C.; Yalk. Ps. I. C.והכל מניפין עליהE todos a admiram.</p><p><strong>Definição:</strong> Para balançar, fã.</p><p><strong>Notas e referências:</strong> Y. Ber. I, 2 dוהיתה רוח … ומְנַפְנֶפֶת בוe o vento do norte soprava e tocava harpa. Yalk. Ps. I. C.שיוצא ומְנַפְנֵף את דגניה(nãoרגליהPesik. R.L.C.ומְנַפֵּף את הדגניםOhol. VIII, 5טלית המְנַפְנֶפֶתUma folha suspensa como uma bandeira (cmp.מַפָּה).</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> para ser winnowed.</p><p><strong>Notas e referências:</strong> Yeb. 63 a (endereça as orelhas no campo, em Chald. dict.)אֵי במנפה תִתְנוֹפְפִיAr., eh! você deseja ser winnow com o ventilador; [oth. vers. em ar.:כמנפה תתנופפי(nãoבמנ&quot;) você se balança como um balanço, v. infra]; ed. v. próximo w.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Para balançar a si mesmo, para voar, para ser orgulhoso.</p><p><strong>Notas e referências:</strong> Ab. Zar. 24 b.הִתְנוֹפְפִי וכ&#x27; subir (Ó Arca) no &amp;c., v.הָדָר* Gen. R. s. 54.</p>","gloss_language":"pt-BR"},{"sid":"N00388","lemma":"נוּף","gloss":"Balance, acene, winnow.; , Ithp.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> A mesma parte.נָיֵיףYeb. 63 aחזנהו דקא נַיְיפָןEle os viu acenando.</p><p><strong>Definição:</strong> Balance, acene, winnow.</p><p><strong>Notas e referências:</strong> Targ. Is. XIII, 2. Y. II Lev. VII, 30מְנִיפָה, v. חוּשְׁלָא.</p><p><strong>Definição:</strong> , Ithp.</p><p><strong>Notas e referências:</strong> אִתְנִיף, אִתְנוֹףPara balançar a si mesmo, para ser orgulhoso. Yeb.אִתְנִיפָא אִיתְנוֹפְפִי וכ&#x27;Ar. (NãoתניפאO comércio de negócios traz mais lucro do que tu; Ed.אי נַיְיפַת אִיתְנוֹפִיComo você acena! (Rashi)אי תנפינו, leia:אִיתְנוֹפוּouאִיתְנִיפוּ).</p>","gloss_language":"pt-BR"},{"sid":"N00389","lemma":"נוֹף","gloss":"Nof, Memphis no Egito.","type":"pr. n. pl.","detailsHtml":"<p><strong>Informações do original:</strong> נֹף)</p><p><strong>Informações do original:</strong> (b. h.</p><p><strong>Definição:</strong> Nof, Memphis no Egito.</p><p><strong>Notas e referências:</strong> Pesik. R. s. 17; Pesik.מִנְפִּיס.</p>","gloss_language":"pt-BR"},{"sid":"N00390","lemma":"נוֹף","gloss":"galhos de uma árvore, galhos balançando, cume.","type":"Substantivo masculino","detailsHtml":"<p><strong>Informações do original:</strong> נוּף)</p><p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> galhos de uma árvore, galhos balançando, cume.</p><p><strong>Notas e referências:</strong> Y. Ber. I, bot 2 c.לא סוף דבר נוֹפוֹ וכ&#x27; (NãoטפוAfinal de contas, não só seus ramos balançando, mas até mesmo seus ramos principais (extendeu-se sobre uma área de &amp; c.). Macc. II, 7אילן … ונופו נוטה וכUma árvore que está dentro dos limites (do lugar de refúgio), mas cujos galhos se espalham além de Maasr. III, 10הכל הולך אחר הנA localização dos ramos decide a natureza do território, Tosef. Arakh. V, 14הנִיף. Kidd. 40 B; A.E. — Pl.נוֹפִים, נוֹפִין, נוֹפוֹת20 Rs.מי שאינו בקי קוצץ את הנ&#x27; וכAquele que não é especialista (em árvores derrubadas) tira os galhos, cada ramo separadamente, e fica cansado. Yalk. Ps. 755 (ref. toיפה נוף, Ps. XLVIII, 3)יפה בנ&#x27; שלה בהקפת וכEla (Israel) é linda com seus ramos acenando ao marchar ao redor do altar (na festa de Booths); Pesik. R.S. 41יפה שלהFriedm. Emendasיָפֶה נוף שלה).</p>","gloss_language":"pt-BR"},{"sid":"N00391","lemma":"נוֹפָא","gloss":"ch.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> ch.</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Notas e referências:</strong> Mesmo. Targ. II Reis XIX, 30פרי). Targ. Ez. XIX, 10; e.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Notas e referências:</strong> = נַפְיָא, q. v.</p>","gloss_language":"pt-BR"},{"sid":"N00392","lemma":"נופי","gloss":"Ver נִינְפֵי.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> Ki Thisa 18, v.נִינְפֵי</p>","gloss_language":"pt-BR"},{"sid":"N00393","lemma":"נוֹפֶךְ","gloss":"Uma jóia, V.נֹפֶךְ.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> Uma jóia, V.נֹפֶךְ.</p>","gloss_language":"pt-BR"},{"sid":"N00394","lemma":"נוֹפֶךְ","gloss":"(הָפַךְ; cmp.אַפּוּכִי) troca, consideração.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> (הָפַךְ; cmp.אַפּוּכִי) troca, consideração.</p><p><strong>Notas e referências:</strong> B. Kam. 99 b; Kidd. 48 bאם הוסיף לה נ&#x27; משלוSe ele deu a ela uma consideração (uma pequena moeda) por conta própria.</p>","gloss_language":"pt-BR"},{"sid":"N00395","lemma":"נוּפָר","gloss":"Ver נִיפָר.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. נִיפָר</p>","gloss_language":"pt-BR"},{"sid":"N00396","lemma":"נוֹפֶת","gloss":"farinha peneirada, pó de farinha;; O mel de rede, favo de mel.","type":"Substantivo feminino","detailsHtml":"<p><strong>Informações do original:</strong> נֹפֶת; denom. deנָפָה)</p><p><strong>Informações do original:</strong> (b. h.</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> farinha peneirada, pó de farinha;</p><p><strong>Número da acepção:</strong> 2)</p><p><strong>Definição:</strong> O mel de rede, favo de mel.</p><p><strong>Notas e referências:</strong> Sot. IX, 12בטל … ונ&#x27; צופיםO shamir cessou e o nofeth tsufim; ib. 48 bמאי נ&#x27; צ&#x27; סולת שצפה ע&quot;ג נפהO que significa N.T.? Farinha fina que flutua no topo da peneira.שתי ככרות וכDois pães presos em paredes opostas do forno, que se levantam para que se toquem uns aos outros.דבש הבא מן הצופיםRashi (ed.מן הציפיא) mel que vem de Tzofim (v.צוֹפִים); Y. ib. IX, 24 b bot.דבש הבא בצפייה, v. צִיפְיָא- Gen. R. s. 71 (jogar emנפ̇ת̇ל̇י̇) נ̇פ̇ת̇ עצמה לא של̇י̇ היא(nãoעצמוNão é meu o favo de mel em si? (Allud. para Ps. XIX, 11); Yalk. ib. 127. Ekeb 1...שאין בכל מיני שהיא צפה בנפה וכ&#x27; (NãoבפהPara todos os tipos de farinha de grãos não há ninguém mais precioso do que a farinha de trigo fino que adere ao crivo, mas as palavras da Lei são mais preciosas do que ela, pois lemos (Ps. l. c.), &#x27;mais doce do que mel e pó de farinha&#x27; Yalk. Ps. 676.נופתי פיתיתיAlguns ed., v.יָסַת.]</p>","gloss_language":"pt-BR"},{"sid":"N00397","lemma":"נוּץ","gloss":"Ver נָצַץ.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> h., v. נָצַץ</p>","gloss_language":"pt-BR"},{"sid":"N00398","lemma":"נוּץ","gloss":"Ver נִיץ.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> ch., v.נִיץ</p>","gloss_language":"pt-BR"},{"sid":"N00399","lemma":"נוֹצָה","gloss":"(b. h.; = נוֹצְאָה; יָצָא); Penas, para baixo.; compararצוֹאָה) Maw contendo as fezes (=קורקבן).","type":"Substantivo feminino","detailsHtml":"<p><strong>Definição:</strong> (b. h.; = נוֹצְאָה; יָצָא)</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Penas, para baixo.</p><p><strong>Notas e referências:</strong> Tudo bem. III, 4אם נטלה הנ&#x27; se a queda está perdida, contradiga. paraכָּנָף; Tosef. ib. III (IV), 18נוֹצָאIb. VI, 11.והסיר את המוראה ואת הנ&#x27; וכEle deve remover a colheita e a pele coberta com as entranhas que a acompanham, ib. 65 aבנוצתה נוטל את הנ&#x27; עמה&quot;Com sua plumagem&quot; (Lev. I, 16), ele deve tomar a plumagem que a cobre com a colheita; Sifra Vayikra, N&#x27;dab., ch. VIII, Par. 7יטלנה עם הנ&#x27;; a. fr. - Sabb. 28 bנ&#x27; של עזיםCabras-cabelo</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> compararצוֹאָה) Maw contendo as fezes (=קורקבן).</p><p><strong>Notas e referências:</strong> Zeb. L.C. (Expl.בנצתה, Lev. l. c.)נוטלה ונוטל וכ&#x27; ele pega (a colheita) e leva o mamilo com ele; Sifra l. c.</p>","gloss_language":"pt-BR"},{"sid":"N00400","lemma":"נוצחייא","gloss":"Ver נָצוֹחָא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. נָצוֹחָא</p>","gloss_language":"pt-BR"},{"sid":"N00401","lemma":"נוּצְיָא","gloss":"Ver נָצָא II.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. נָצָאII</p>","gloss_language":"pt-BR"},{"sid":"N00402","lemma":"*,","gloss":"(v. נוֹצָה) penas, pinhão.","type":"Substantivo feminino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: *נוֹצִיצְיָא</p><p><strong>Definição:</strong> (v. נוֹצָה) penas, pinhão.</p><p><strong>Notas e referências:</strong> Targ. Trabalho XXXIX, 13נוֹצִיצְיָיהָאLag.נוֹצִצְיָיהָאSra.נִיצוֹצְיָהָא); [ed. Wil.נוֹצִיצְיֵתָאPelicano (?)].</p>","gloss_language":"pt-BR"},{"sid":"N00403","lemma":"נוֹצְרִי","gloss":"Nazareno, de Nazaré (no sul de Galilaea).","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> Nazareno, de Nazaré (no sul de Galilaea).</p><p><strong>Notas e referências:</strong> —ישו הנJesus de N. Snh. 43 a Srta.יֵשׁוּ-Ab. Zar. 7b.יום נSra. M. (v. Rabb. D. A. L. Nota; Ed.יום א&#x27;) o dia do Nazareno (domingo). Pl.נוֹצְרִיםCristãos. Taan. 27b.מפני הנM. (ed.העב&quot;ום; em alguns ed. a passagem inteira omitida) por conta (para não ser identificado com) os cristãos (v. Trato. Sof’rim ch. XVII, 5.</p>","gloss_language":"pt-BR"},{"sid":"N00404","lemma":"נוֹצְרִין","gloss":"Ver נֵצֶר III.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> Tosef. Toh. XI, 16, v.נֵצֶרIII</p>","gloss_language":"pt-BR"},{"sid":"N00405","lemma":"נוּקְבָּא","gloss":"Buraco, V.נִקְבָּא.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: נוּקְבָא</p><p><strong>Definição:</strong> Buraco, V.נִקְבָּא.</p>","gloss_language":"pt-BR"},{"sid":"N00406","lemma":"נוּקְבָא","gloss":", mulher.","type":"Substantivo feminino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: נוּקְבָה, נוּקְבְתָא</p><p><strong>Informações do original:</strong> נְקֵבָה</p><p><strong>Informações do original:</strong> ch. = h.</p><p><strong>Definição:</strong> , mulher.</p><p><strong>Notas e referências:</strong> Targ. Gen. I, 27 anos. IV, 69 um bot. Gen. R. s. 33, v.דְּכַרII; a. fr. — Pl.נוּקְבִין, נוּקְבָן, נוּקְבֽתָאKeth.בַּרY. Y. Kil. IX, 32 b; Y. Keth. XII, 35 a bot.; Gen. R. l. c., v.דְּכַרII, A. E.</p>","gloss_language":"pt-BR"},{"sid":"N00407","lemma":"נוּקְבְּתָא","gloss":"Ver נְקִיפְתָּא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> P.N.P., V.נְקִיפְתָּא</p>","gloss_language":"pt-BR"},{"sid":"N00408","lemma":"נוֹקֵד","gloss":"Pastor.","type":"Substantivo masculino","detailsHtml":"<p><strong>Informações do original:</strong> נֹקֵד; נָקַד I)</p><p><strong>Informações do original:</strong> (b. h.</p><p><strong>Definição:</strong> Pastor.</p><p><strong>Notas e referências:</strong> Pesik. Shek., p. 12 b; ib. Eth Korb., p. 60 a; Pesik. R. s. 16; Tan. Ki Thissa 5מהו נ&#x27; רועהO que é noked (II Reis III, 4)? Um pastor.</p>","gloss_language":"pt-BR"},{"sid":"N00409","lemma":"נוּקָּד","gloss":"(נָקַדI; cmp. árabe.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> (נָקַדI; cmp. árabe.</p><p><strong>Notas e referências:</strong> Uma moeda carimbada. Par. I, 3בן עזאי קירהו נ&#x27; וכBen Azzai chamou de &quot;ovelhas entre um e dois anos de idade, quando não é nada&quot;.כֶּבֶשׂnemאַיִל) &#x27;uma moeda distinta;&#x27; R. Yishm. chamado de &quot;falsificação&quot;; v.פָּרָכָרַגְמָא.</p>","gloss_language":"pt-BR"},{"sid":"N00410","lemma":"נוֹקְדָן","gloss":", V. Subנַקְדָּ'.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: נוֹקְדָנָא</p><p><strong>Notas e referências:</strong> , V. Subנַקְדָּ&#x27;.</p>","gloss_language":"pt-BR"},{"sid":"N00411","lemma":"נוקל","gloss":"Ver נוּ.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , Y. Yeb. X, 11 a bot., v.נוּ</p>","gloss_language":"pt-BR"}],93);
